/* ========================================
   HTML SITEMAP - DGS BRAND DESIGN
   ======================================== */

.dgs-sitemap-wrapper * {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

.dgs-sitemap-wrapper {
  position: relative;
  background: transparent;
  font-family: 'Space Grotesk', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  overflow: hidden;
}

.dgs-sitemap {
  position: relative;
  padding: clamp(80px, 10vw, 120px) clamp(20px, 4vw, 40px);
  background: transparent;
}

.dgs-sitemap-container {
  max-width: 1400px;
  margin: 0 auto;
  position: relative;
  z-index: 1;
}

/* Header */
.dgs-sitemap-header {
  text-align: center;
  margin-bottom: clamp(60px, 8vw, 80px);
}

.dgs-sitemap-pretitle {
  font-size: clamp(0.75rem, 1.3vw, 0.85rem);
  font-weight: 300;
  letter-spacing: 3px;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.5);
  margin-bottom: 20px;
}

.dgs-sitemap-title {
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 300;
  color: #fff;
  margin-bottom: 20px;
  letter-spacing: -0.03em;
  line-height: 1.15;
}

.dgs-sitemap-title-gradient {
  background: linear-gradient(90deg, #00D4FF 0%, #FF00DC 50%, #FF6B35 100%);
  background-size: 200% 100%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: gradientSlideSitemap 8s linear infinite;
  font-weight: 400;
}

.dgs-sitemap-description {
  font-size: clamp(0.95rem, 1.5vw, 1.1rem);
  font-weight: 300;
  color: rgba(255, 255, 255, 0.65);
  max-width: 700px;
  margin: 0 auto;
  line-height: 1.6;
}

/* Grid */
.dgs-sitemap-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: clamp(30px, 4vw, 40px);
}

.dgs-sitemap-section {
  background: transparent;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 16px;
  padding: clamp(28px, 4vw, 35px);
  transition: all 0.4s ease;
}

.dgs-sitemap-section:hover {
  border-color: rgba(255, 107, 53, 0.25);
  transform: translateY(-5px);
  box-shadow: 0 10px 30px rgba(255, 107, 53, 0.1);
}

.dgs-sitemap-section-title {
  font-size: clamp(1.1rem, 1.6vw, 1.3rem);
  font-weight: 400;
  color: rgba(255, 255, 255, 0.95);
  margin-bottom: clamp(20px, 3vw, 25px);
  letter-spacing: 0.3px;
  position: relative;
  padding-bottom: 12px;
}

.dgs-sitemap-section-title::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 40px;
  height: 2px;
  background: linear-gradient(90deg, #00D4FF 0%, #FF00DC 50%, #FF6B35 100%);
  border-radius: 10px;
}

.dgs-sitemap-links {
  list-style: none;
  padding: 0;
  margin: 0;
}

.dgs-sitemap-link-item {
  margin-bottom: 12px;
}

.dgs-sitemap-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: clamp(0.85rem, 1.25vw, 0.95rem);
  font-weight: 300;
  color: rgba(255, 255, 255, 0.6);
  text-decoration: none;
  transition: all 0.3s ease;
  letter-spacing: 0.3px;
}

.dgs-sitemap-link::before {
  content: '→';
  opacity: 0;
  color: #FF6B35;
  transition: all 0.3s ease;
  transform: translateX(-10px);
}

.dgs-sitemap-link:hover {
  color: rgba(255, 255, 255, 0.95);
  padding-left: 15px;
}

.dgs-sitemap-link:hover::before {
  opacity: 1;
  transform: translateX(0);
}

@keyframes gradientSlideSitemap {
  0% { background-position: 0% 50%; }
  100% { background-position: 200% 50%; }
}

/* Responsive */
@media (max-width: 968px) {
  .dgs-sitemap {
    padding: clamp(60px, 8vw, 80px) clamp(20px, 4vw, 30px) !important;
  }

  .dgs-sitemap-grid {
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: 25px;
  }

  .dgs-sitemap-section {
    padding: 25px;
  }
}

@media (max-width: 580px) {
  .dgs-sitemap {
    padding: 50px 20px !important;
  }

  .dgs-sitemap-grid {
    grid-template-columns: 1fr;
    gap: 20px;
  }

  .dgs-sitemap-link:hover {
    padding-left: 0;
  }

  .dgs-sitemap-link::before {
    display: none;
  }
}

